test-case.test:
   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item()*);
	declare function _:make-map($entries as type(entry)*) as map(*) {
	   map:merge($entries ! map{ ?name : ?value })
	};
	declare function _:entry($name as xs:string, $value as item()*) as type(entry) {
	   map{ "name":$name, "value": $value }
	};
	let $temp := _:make-map(( 
	  _:entry("A", 23),
	  _:entry("B", 32),
	  _:entry("C", 89)))
	return $temp?A

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item());
	declare function _:make-map($entries as type(entry)*) as map(*) {
	   map:merge($entries ! map{ ?name : ?value })
	};
	declare function _:entry($name, $value) as type(entry) {
	   map{ "name":$name, "value": $value }
	};
	let $temp := _:make-map(( 
	  _:entry("A", 23),
	  _:entry("B", 32),
	  _:entry("C", 89)))
	return $temp?A

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item()?);
	map{"name":"xyz"} instance of type(entry)

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item()?);
	map{"name":"xyz", "value":()} instance of type(entry)

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item()?);
	declare function _:f($arg as type(entry)) as xs:boolean {
	    $arg?extra = 3
	};
	_:f(map{"name":1, "value":(), "extra":3})

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:numeric, value as item()?, *);
	declare function _:f($arg as type(entry)) as xs:boolean {
	    $arg("extra") = 3
	};
	_:f(map{"name":1, "value":(), "extra":3})

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as item()*, value as item()+);
	map{"name":"xyz"} instance of type(entry)

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type entry = tuple(name as xs:string, value as item()*);
	declare function _:f($arg as type(entry)) as xs:boolean {
	    $arg("extra") = 3
	};
	_:f(map{"name":1, "value":(), "extra":3})

   declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
   declare namespace _ = "http://local/";
   declare type s = xs:nonNegativeInteger;
   declare type entry = tuple(key as type(s), value as item()*);
	declare function _:f($arg as type(entry)) as xs:boolean {
	    $arg?key = 3
	};
	_:f(map{"key":1 cast as xs:positiveInteger, "value":()})
